INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alleykat', 28850, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mywtpdjnjytdvixg9yen.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scort0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alleykat', 'Alleykat is a vertically-scrolling racer with elements of a shoot-em up game. The player, a speeder pilot, strives to become the Alleykat Champion by competing in eight space stadiums scattered around the galaxy. Different races like demolition derbies, time-trials, endurance epics and others feature all kinds of obstacles like rocks, pillars, bridges and hard walls, and several types of enemies race along. The game also features a cooperative two-player-mode.' FROM games WHERE igdb_id = 28850 ON CONFLICT (game_id, language_code) DO NOTHING;
