INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yami no Ryuuou Hadesu no Monshou', 'Casio''s Yami no Ryūō Hadesu no Monshō is a clone of Konami''s Knightmare. In this top-view game you control a brave and handsome knight, Leon, that has to shoot bullets at various types of enemies. Shooting a series of enemies can grant you invulnerability or a shield. You have to avoid obstacles and shoot at them at the same time because they can contain power-ups for your weapons. At the end of each level is an end boss that has to be defeated before you can continue to the next level.' FROM games WHERE igdb_id = 202322 ON CONFLICT (game_id, language_code) DO NOTHING;
