INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrust', 'The aim of this shooter game is to pilot a spacecraft which must pick up a pod using a tractor beam and fly it into space. The ship and pod are subject to gravity and inertia, and being connected by a stiff rod, they can end up spinning around each other, out of control. Hitting the walls of the cave with either the ship or the pod results in death.' FROM games WHERE igdb_id = 12967 ON CONFLICT (game_id, language_code) DO NOTHING;
