INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Mission', 'The players assume the role of an alien-humanoid space pilot who has been exiled from their home galaxy for committing an unlearned crime. The only way the player character can return is to restore their honor; the only way to do so is to invade and defeat the alien invaders who have been known to frequently attack the player character''s people using a ship called the Main Fighter.' FROM games WHERE igdb_id = 40083 ON CONFLICT (game_id, language_code) DO NOTHING;
