INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titanic: The Recovery Mission', 'The game combines both above and below water aspects. Above the water, you must manage the company, press conferences and finances. Below the water, you explore the Titanic and her many secrets by navigating T.S.1 (your underwater robot) through a maze-like environment while trying to find a way to raise the ship to the surface.' FROM games WHERE igdb_id = 12962 ON CONFLICT (game_id, language_code) DO NOTHING;
