INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix and the Magic Cauldron', 'Based on the French comic heroes Asterix & Obelix, the game is a side-scrolling beat-em up developed by Krome Studios in 1986. In super early previews from old UK magazines, you can see a tiny Asterix sprite for the C64 version but when it hit shelves worldwide, it was already renamed to Ardok the Barbarian' FROM games WHERE igdb_id = 13339 ON CONFLICT (game_id, language_code) DO NOTHING;
