INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vs. Super Mario Bros.', 'Vs. Super Mario Bros. is a two-player VS. System version of Super Mario Bros. This game has higher gameplay difficulty than the original Super Mario Bros., with fewer warp zones and power-ups, and more enemies. Six new levels were created for the game, all of which were reused in Super Mario Bros.: The Lost Levels.' FROM games WHERE igdb_id = 92342 ON CONFLICT (game_id, language_code) DO NOTHING;
