INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball: Dragon Daihikyou', 'Dragon Ball: Dragon Daihikyou is the first Dragon Ball console video game ever released. It was developed and released by Epoch in September 27, 1986, for the Super Cassette Vision console, making it the only Dragon Ball game not produced or distributed by Bandai or the subsequent Namco Bandai.' FROM games WHERE igdb_id = 66405 ON CONFLICT (game_id, language_code) DO NOTHING;
