INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mean 18: Ultimate Golf', 'Mean 18 is a golf video game designed by Rex Bradford with graphics by George Karalias, both of Microsmiths, and released by Accolade for MS-DOS compatible operating systems in 1986. It was ported to the Amiga, Apple IIGS, Atari ST, and Macintosh. It includes an editor allowing players to create their own courses. In 1989, Atari Corporation published a port for the Atari 7800 console. A version for Atari 8-bit computers was in development in 1989 but was cancelled.' FROM games WHERE igdb_id = 14781 ON CONFLICT (game_id, language_code) DO NOTHING;
