INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ernies-big-splash', 213131, '1986-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co52nx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scibo8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ernie''s Big Splash', 'Ernie''s Big Splash is a 1986 Sesame Street video game starring Rubber Duckie. The goal was to create a series of connections, for Rubber Duckie to make his way to Ernie''s bathtub. The game teaches basic logic, directions (North, South, East and West) and sequencing. The video game was created by CBS Learning Systems, for ages four to six. The game was originally made for DOS, but was released for the Nintendo Entertainment System in 1989. On NES, it was released on the cartridge Sesame Street ABC, supplementing Letter-Go-Round. At some point in time, the game was released for the Unisys ICON operating system, a platform commissioned by the Ontario education system. No copies of this format exist, as the last ICON computers and software were destroyed in the early-2000s.' FROM games WHERE igdb_id = 213131 ON CONFLICT (game_id, language_code) DO NOTHING;
