INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('climber--1', 125338, '1986-07-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b34.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3pca.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Climber', 'Climber is a Game & Watch video game released in the Crystal Screen format in 1986 and the New Wide Screen format in 1988. The game was never released in Japan, and an estimated 250,000 of the New Wide Screen version were produced by Nintendo. The model number for the Crystal Screen version is DR-802, while the model number for the New Wide Screen game is DR-106. Some speculate that the game is based on the Ice Climber NES game, though this is unconfirmed. In Climber, you are a child known as Climber who, with the help of Lord Meiji''s teachings, jumps across platforms trying to get to the top of Block Mountain while avoiding enemies and platforms that move. The enemies are the Blockmen, which walk and turn into block platforms when they reach a gap; Eyerom, birds that fly and get in the Climber''s way; and thorny plants, which are obstacles in the way of Climber''s movements. In each set of 5 levels, the first 4 ends with a bonus game where Climber has 2 chances to time his jump to catch Hentori, the bonus bird. On the fifth level, Climber must jump and grab the sword at the correct time to stab and defeat Dragalo the dragon.' FROM games WHERE igdb_id = 125338 ON CONFLICT (game_id, language_code) DO NOTHING;
