INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wibarm', '"Wibarm", is an early role-playing shooter, combining run and gun shooter gameplay with role-playing video game elements. In Wibarm, the player controls a transformable mecha robot that can shift between walking mode, a tank, and a flying jet. The viewpoint switches between several different perspectives: a 2D top-down perspective while flying, a side-scrolling view during on-foot outdoor exploration, a fully 3D polygonal third-person perspective inside buildings, and arena-style 2D shoot ''em up battles during boss encounters.' FROM games WHERE igdb_id = 84248 ON CONFLICT (game_id, language_code) DO NOTHING;
