INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid', 'Metroid was first released for the Famicom Disk System, exclusively in Japan. Due to the enhanced hardware support, it features a save system, has less slowdown and better quality music. However, when comparing with its International version, it doesn''t have the second quest after beating the game, the players can''t use Justin Bailey Samus (Zero Suit) and it is much lenient on difficulty and endgame requirements.' FROM games WHERE igdb_id = 342602 ON CONFLICT (game_id, language_code) DO NOTHING;
