INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Topple Zip', 'Topple Zip is a vertically scrolling shooter that is marketed as a racing game. The basic premise is that you control an aircraft and fly in competition against several other, computer controlled crafts. In addition to shooting at your opponents, you may ram into them, and they into you. Doing so may dislodge a pill shaped power-up from them which you can then shoot and collect.' FROM games WHERE igdb_id = 41316 ON CONFLICT (game_id, language_code) DO NOTHING;
