INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroic Episode', 'Heroic Episode is a 2D top-down fantasy shooter, similar to Commando or Ninja Princess in an ancient land. The player controls a small, bearded man who wears a horned helmet, goes straight forward and shoots various enemies and bosses. He has unlimited bullets, but the weapon has a very limited range.' FROM games WHERE igdb_id = 98169 ON CONFLICT (game_id, language_code) DO NOTHING;
