INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kikstart-ii', 12658, '1986-12-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93ar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nyzbkxbztne7duxph6t8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kikstart II', 'Kikstart 2 is a motorcycle trials racing videogame released for the Amiga, Amstrad CPC, Commodore 64 and ZX Spectrum. It enjoyed more success than its predecessor, Kikstart. The game allowed 2-player simultaneous (via a split-screen facility) or 1-player, vs-computer play. The game mechanics were copied into other games too, like the Game Boy game "Motocross Maniacs". The basic premise of the game is to control a bike using acceleration, braking, "hopping" and "wheelies" to navigate across a course of various obstacles, from ramps and gates to telephone boxes and tyres. The game was based on the BBC Television series Kick Start. An enhanced version was released for the Commodore 128,[1] one of the few native mode game titles for that computer. Source: https://en.wikipedia.org/wiki/Kikstart_2' FROM games WHERE igdb_id = 12658 ON CONFLICT (game_id, language_code) DO NOTHING;
