INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Soccer', 'Super Soccer is a soccer simulation developed for the Spectrum 48/128 by Imagine Software in 1986. It was also later released by Ocean Software as a free game with Crash Magazine. Control is either with joystick or keyboard. gameplay is either single player against computer teams, or up to 8 players in a turn-based multiplayer mode. Games last about 5 minutes, and a timer counts this down, but stops to wait for penalties, free kicks, half-time, etc. The player controls one team member at a time, and this player is shown by a halo above their head. If this player moves away from the ball too far or for too long, control is switched to the next nearest player on the football field. Players with highest score at the end win the match.' FROM games WHERE igdb_id = 235103 ON CONFLICT (game_id, language_code) DO NOTHING;
