INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hudson''s Adventure Island', 'Hudson''s Adventure Island, also known simply as Adventure Island and released in Japan as Takahashi Meijin no Bouken-jima, is a side-scrolling platform game produced by Hudson Soft that was first released in Japan for the Famicom and MSX on September 12, 1986. It was later released in North America for the Nintendo Entertainment System on September 1988 and in the PAL region in 1992 under the title of Adventure Island Classic. Adventure Island is an adaptation of the arcade game Wonder Boy, originally published by Sega for developer Escape (now known as Westone Bit Entertainment). Adventure Island was followed by a series of sequels that were independently developed by Hudson Soft.' FROM games WHERE igdb_id = 4594 ON CONFLICT (game_id, language_code) DO NOTHING;
