INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great Escape', 'The Great Escape is an isometric action-adventure game. Controlling a prisoner of war in a German camp, your goal is to break out undetected. There are numerous ways to freedom - back doors, cracked fences, even underground tunnels. However, you have to plan your escape while obeying the strict rules of the camp.' FROM games WHERE igdb_id = 28852 ON CONFLICT (game_id, language_code) DO NOTHING;
