INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganso Saiyuuki: Super Monkey Daibouken', 'Sun Wukong must assist the Buddhist monk Xuanzang with his task of collecting some sūtras as they make the treacherous voyage from China to India. Other guardians can be asked to join the adventuring party after meeting up with them. Most of the storyline in this video game is based on the Chinese novel Journey to the West. Players can enter a code that allows them to return to any stage at any time.' FROM games WHERE igdb_id = 48487 ON CONFLICT (game_id, language_code) DO NOTHING;
