INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liberator', 'Written by D. R. Gamon this space shoot''em up is similar to Andrew Braybrook''s Uridium. It was originally released by Magnificent 7 in a compilation called "Liberator / Space Fiends" in 1986 for Commodore 16. In 1987 Alternative Software re-released it as a single game.' FROM games WHERE igdb_id = 159066 ON CONFLICT (game_id, language_code) DO NOTHING;
