INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3d-thunder-ceptor-ii', 146255, '1986-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ynj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmhr6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Thunder Ceptor II', 'A sequel to Thunder Ceptor. The game is very much like the original; the player controls the Thunder Ceptor (now colored light blue), and must shoot the incoming crafts (now colored from gray to green) as normal. There are now multiple obstacles, including large rods, and flying panels (like the Bacura from Xevious), and the obstacles can now be destroyed with the bombs, now no longer having to avoid them. As the name suggests, the game is playable in 3D, and is the only Namco arcade game to do so. The player would put their head up to the attached goggles on the machine for the 3D effect.' FROM games WHERE igdb_id = 146255 ON CONFLICT (game_id, language_code) DO NOTHING;
