INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('riglas', 281255, '1986-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ke4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq0fl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riglas', 'The continent of Riglas is inhabited by two races: the Mirians and the Galtians. For years they have fought each other for dominance. Caught in the struggle between the two is the nearly forgotten Osborn race, discriminated and enslaved. Mei, a young Osborn man, leaves his home village in order to free his people, and to discover the forbidden secrets of Beljuna which remain a taboo in this land. This side-scrolling action role-playing adventure is set in a vast seamless world that consists of interconnected yet varied urban, wilderness, and dungeon-like locations. Players can explore all of Riglas from the outset, a world populated by many different types of friendly and hostile characters. Killing hostiles increases the player''s score and eventually makes the main character stronger. Killing friendlies, on the other hand, may lower the score. Combat is simple: approach a character and press the attack button to swing Mei''s sword.' FROM games WHERE igdb_id = 281255 ON CONFLICT (game_id, language_code) DO NOTHING;
