INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bombo', 293252, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91az.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombo', 'Bombo is a fast-paced arcade-style platformer where players control a character jumping across the screen to collect tokens while avoiding enemies. The game''s core gameplay revolves around quick reflexes and strategic movement as players aim to gather all tokens, with added bonuses for collecting them in the correct flashing order. Power-ups occasionally fall from above, temporarily granting the ability to capture enemies for points. With only three lives at their disposal, players must balance speed and caution to progress. Bombo''s simple yet challenging mechanics, combined with its time-limited power-ups and bonus scoring system, create an addictive and engaging experience reminiscent of classic arcade games.' FROM games WHERE igdb_id = 293252 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 293252 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
