INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('i-am-a-teacher-teami-no-kiso', 41374, '1986-09-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wy47xkuse9i8xyjg3kmc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scp3hk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am a Teacher: Teami no Kiso', 'An instructional program for learning how to knit by hand for the Famicom Disk System. It was developed by Royal Kougyou and follows their earlier educational software I Am a Teacher: Super Mario no Sweater. I Am a Teacher: Teami no Kiso (roughly "I Am a Teacher: The Basics of Hand-Knitting") is an instructional tool to help would-be knitters create their own garments. The user can input the amount, length and type of wool they have and the size and type of the item of clothing they wish to create and the program will put together a guide to help them achieve this goal. The user can save their progress at any time and pick up from where they left off. Unlike Super Mario no Sweater, its predecessor in the I Am A Teacher series, there are no Nintendo characters present in Teami no Kiso. Rather, Teami no Kiso is a guide for teaching the fundamentals of knitting to novices, with Super Mario no Sweater intended for those who already have some experience who wish to try new Mario-themed designs. As with Super Mario no Sweater, Teami no Kiso was commissioned by major Japanese wool and sewing products manufacturer Royal Kougyou, but it''s believed that Nintendo developed and published the game themselves.' FROM games WHERE igdb_id = 41374 ON CONFLICT (game_id, language_code) DO NOTHING;
