INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo', 'Join the Scooby gang as they try to solve the mystery of Spooky Island. Players will roam the movie locations in search of clues, solving a series of small mysteries as they work to uncover the island?s ultimate mystery. Along the way the players will interact with familiar characters, explore environments based on the movie and collect items they can use to trap diabolical villains.' FROM games WHERE igdb_id = 2856 ON CONFLICT (game_id, language_code) DO NOTHING;
