INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TechMate Chess', 'A commercial chess game for the Atari ST by Alexander and Barbara Szabo, produced and market by their own company Szabo Software since 1986 , and distributed also through third party vendors like MichTron Corp. in the US, and Microdeal and Software Direct in the UK. TechMate has an own GUI with 2D Graphics Board and entering moves completely mouse-driven.' FROM games WHERE igdb_id = 327801 ON CONFLICT (game_id, language_code) DO NOTHING;
