INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in the U.S.A. is Carmen Sandiego?', 'As a detective, the player must hunt down Carmen Sandiego''s henchmen, who have stolen outrageous items that are important in US history and heritage. Using clues, the player will follow the henchmen from city to city.' FROM games WHERE igdb_id = 12823 ON CONFLICT (game_id, language_code) DO NOTHING;
