INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-bard-s-tale-ii-the-destiny-knight', 2430, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wak.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/y7mlpo0zclx9ebvsukuq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bard''s Tale II: The Destiny Knight', 'When the going gets even tougher... Another wolf! Your magic sword cleaves him mid snarl, and he drops in a fur pile at your feet. There''s a slime ball conjurer just out of reach who''ll keep summoning these slobbering missiles until your sword arm drops off. Unless you can figure out a way to get at him. When you put Mangar out to pasture, all you really wanted was a bottomless mug and an ace up your sleeve. So what are you doing out here in the gnarly wilderness, knee deep in wolf meat, itching to put an arrow through the Adam''s apple of some spell caster? It must be your destiny. Between the six cities lies an immense wilderness. It''s a mapping challenge never before seen in a fantasy game, and a whole new way to get lost. A new class of magic user, the Archmage has 8 powerful spells like Heal All, Fanskar''s Night Lance, and the legendary Mangar''s Mallet. There are 25 different full-color scrolling mazes like Fanskar''s Castle.' FROM games WHERE igdb_id = 2430 ON CONFLICT (game_id, language_code) DO NOTHING;
