INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lords-of-conquest', 26391, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kziofguekklof4uek4gz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of Conquest', 'The game is based on the board game Borderlands by Eon Productions (best known for their highly acclaimed board game, Cosmic Encounter), and was marketed with the slogan "Better than Risk!" to identify it as a global conquest game similar to Risk. It proved to be one of EA''s best-selling titles of 1986. GameSpy awarded Lords of Conquest a "Gotcha" award as one of the top games of its era.  You and your opponent start by selecting countries in turn from a map. This can be randomly generated based on requested numbers of countries and volumes of water, chosen from one of the 19 predefined ones, or created using the built-in editor.  Your army possesses infantry, cavalry and a water fleet. Natural or produced resources such as gold and iron are identified - countries containing these might be the best ones to invade.You can play at 4 skill levels, and decide how big a factor luck is. With calculations settled by the computer, players can concentrate on the power games.' FROM games WHERE igdb_id = 26391 ON CONFLICT (game_id, language_code) DO NOTHING;
