INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nagagutsu wo Haita Neko: Sekai Isshuu 80-nichi Daibouken', 'Nagagutsu wo Haita Neko: Sekai Isshuu 80-nichi Daibouken is a 1986 video game based on the third film of The Wonderful World of Puss ''n Boots that was released exclusively in Japan for the Family Computer. Four years later, the game (with several modifications) was released in North America under the title Puss ''n Boots: Pero''s Great Adventure. The main character is the Puss in Boots character from the tale; a cat named Pero (Toei Animation''s mascot) He is also known as ''Perrault'' in the game, as that was the name of the original author of the Puss In Boots story; Charles Perrault. He is known for helping an impoverished master attain wealth through the use of trickery.' FROM games WHERE igdb_id = 48416 ON CONFLICT (game_id, language_code) DO NOTHING;
