INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1001 BC: A Mediterranean Odyssey', 'Découvrez un monde fabuleux : celui des poèmes d’Homère. Le réalisme de l’aventure, qui se déroule en temps réel, a été poussé très loin : illustration particulièrement soignée, animations, bruitages, mais aussi interventions inattendues de vos compagnons de voyage, tout contribue à vous projeter dans la légende, parmi les monstres et les dieux antiques dont vous déjouerez les énigmes. Le plus sophistiqué des jeux d’aventures pour CPC.' FROM games WHERE igdb_id = 12353 ON CONFLICT (game_id, language_code) DO NOTHING;
