INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Icarus', 'Kid Icarus is an action platform video game for the Family Computer Disk System in Japan and the Nintendo Entertainment System in Europe and North America. The plot of Kid Icarus revolves around protagonist Pit''s quest for three sacred treasures, which he must equip to rescue the Grecian fantasy world Angel Land and its ruler, the goddess Palutena. The player controls Pit through platform areas while fighting monsters and collecting items. Their objective is to reach the end of the levels, and to find and defeat boss monsters that guard the three treasures.' FROM games WHERE igdb_id = 3663 ON CONFLICT (game_id, language_code) DO NOTHING;
