INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: The Battle to Save the Earth', 'The Transformers: Battle to Save the Earth is a computer game for the Commodore 64 designed by David Crane with music by Russell Lieblich, released in 1986 by Activision. In the game, the Autobot team must defend a number of sites from Decepticon attack. These sites are presented on an overworld map, and the player can dispatch Autobots to these sites via connecting roads. In an attack, gameplay consists of a first-person fixed-perspective shooting game, where the player must prevent an endless army of multi-colored Seekers from stealing various materials.' FROM games WHERE igdb_id = 8016 ON CONFLICT (game_id, language_code) DO NOTHING;
