INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('avengers', 46822, '1986-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tty.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scie90.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avengers', 'Avengers, sometimes known as Avenger, and known in Japan as Hissatsu Buraiken (必殺 無頼拳?, lit. "Deadly Ruffian Fist"), is a 1987 overhead-view vertically scrolling beat ''em up arcade game developed and published by Capcom. The game was directed by Takashi Nishiyama, who later co-planned the original Street Fighter and a few of SNK''s early fighting games. The game takes place in Paradise City, where the villain, "Geshita", has captured 6 girls from the city. The player''s objective (as Ryu or Ko) is to banish "Geshita" from Paradise City once and for all. During the game, the player can pick up powerups like the "Speed Up", the Super Punch, Grenades, Shurikens, Nunchaku and extra health. The game also features hidden areas on each level, accessed by breaking doors in structures on either side of the screen. The player''s character has 3 normal means of attack: Punches, which are quick with short range, Kicks, which are slower with longer range, and the Roundhouse, which hits in a 360 degree motion.' FROM games WHERE igdb_id = 46822 ON CONFLICT (game_id, language_code) DO NOTHING;
