INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mermaid-madness', 28449, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4xmt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mermaid Madness', 'In Mermaid Madness the player takes the role of the weighty mermaid Myrtle who finally, after 112 years, found the man of her dreams: the diver Gordon. Unfortunately he is not very enthusiastic, flees into the water and jams himself under a ship. Myrtle''s first priority is to save Gordon. The player navigates Myrtle through an underwater labyrinth (although there a few screens above ground) and collects items. Those items have to be used in another location to proceed. It is also important to avoid enemies because touching them reduces her life energy, which can be refilled by finding beer bottles. There is no scrolling and Gordon''s air supply acts as time limit.' FROM games WHERE igdb_id = 28449 ON CONFLICT (game_id, language_code) DO NOTHING;
