INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock''n Rage', 'Rock''n Rage is an action shooter developed and published by Konami and released on arcade platforms in 1986. The game is an action shooter game, the player plays as Rick or John and have to go through five mazed levels, each corresponding at one time era, Ancient Egypt, England during medieval times, France during revolution, Italy during roman era and Japan in modern days. Each of these levels concludes with a boss fight. Players start with guitars only as their weapons, but finding potions on the ground will allow them to expand greatly their range of action, such as shooting musicals notes to destroy the various enemies the game offers.' FROM games WHERE igdb_id = 210807 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 210807 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
