INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nobunaga''s Ambition', 'The second game in the series, previously released as Nobunaga''s Ambition in the West. Players take on the role of one of the main characters of the period, Nobunaga Oda, Shingen Takeda, Kenshin Uesugi, or others and try to unite the 50 kingdoms of Japan, from Ezo in the north to Kyushu in the south, under their own rule.' FROM games WHERE igdb_id = 4369 ON CONFLICT (game_id, language_code) DO NOTHING;
