INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kidou Senshi Z Gundam: Hot Scramble', 'Mobile Suit Z Gundam: Hot Scramble is a multi-genre video game that is based on the anime Mobile Suit Z Gundam, and is one of the first Gundam video games. Aside from the much later Famicom Mini release, there were two versions of the game: the original release; and a special release of the central location test version, sometimes dubbed Final Version. Only 1000 copies of this second version were ever released, making it among the rarest video game in history.' FROM games WHERE igdb_id = 48423 ON CONFLICT (game_id, language_code) DO NOTHING;
