INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castlevania', 1114, '1986-09-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coba2o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ksl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania', 'Step into the shadows of the deadliest dwelling on earth. You''ve arrived at Castlevania, and you''re here on business: To destroy forever the Curse of the Evil Count. Unfortunately, everybody''s home this evening. Bats, ghosts, every kind of creature you can imagine. You''ll find ''em all over the place, if they don''t find you first. Because you''ve got to get through six monstrous floors before you even meet up with the Master of the House. Your Magic Whip will help, and you''ll probably find a weapons or two along the way. But once you make it to the tower, you can count on a Duel to the Death. The Count has waited 100 years for a rematch.' FROM games WHERE igdb_id = 1114 ON CONFLICT (game_id, language_code) DO NOTHING;
