INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('annals-of-rome', 11903, '1986-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gcc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arn3x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Annals of Rome', 'Annals of Rome begins in 273BC and sets you as a Roman senator, with the ultimate aim of colonizing as much of the known world as possible, and retaining that power against Carthaginians, Vandals, Parthians, Persians and all the other world forces. You have a strong army at your disposal, and can direct your generals as to which countries they attempt to invade. The game is turn-based, and these turns operate in phases, beginning with the economic circumstances of population and tax income being decided - it''s recommended to keep taxation taxing low unless things become desperate. The game then updates you on the statuses of your generals, and give you the chance to redistribute them to other parts of your kingdom. Officers may rebel and cause a civil war - fortunately this can usually be pre-empted. More serious are attempts to take land from other civilizations, which take place in order and include conflicts between other groups. These, like every element of the game, are accurately historically modeled and variable in time-span as a result.' FROM games WHERE igdb_id = 11903 ON CONFLICT (game_id, language_code) DO NOTHING;
