INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quartet', 36677, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7e95.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/alqpqelv7kxvmerhxtbs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quartet', 'A platform shoot-em-up hybrid from Sega for one to four players, selected from either Joe (yellow), Mary (red), Lee (blue) and Edgar (green). The action takes place over a number of sideways scrolling levels, the bulk of which consist of straightforward platform action. On some levels, however, there are jet packs for the players to collect, and the gameplay''s emphasis switched to that of a standard, sideways scrolling shoot-em-up. The object of the game is to destroy an army of robots that have taken over an Earth colony satellite station. Each level has a boss character that must be destroyed. Upon its death it releases a door key that must be used to exit the level. Weapon and character power-ups can be collected to aid players in their task. Due to its potential for four-player shoot-em-up gameplay, Quartet''s gameplay feels vaguely similar to (though by no means as accomplished as) Atari''s 1985 classic, "Gauntlet".' FROM games WHERE igdb_id = 36677 ON CONFLICT (game_id, language_code) DO NOTHING;
