INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rolling-thunder', 12846, '1986-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3o6u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schtz4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rolling Thunder', 'Rolling Thunder is a run and gun/action arcade game that was released by Namco in 1986 and licensed to Atari Games for US manufacture and distribution. It runs upon Namco System 86 hardware, and was later converted for the Sinclair ZX Spectrum, the Commodore 64, the Amstrad CPC, the Atari ST, the Commodore 64, and the Nintendo Family Computer. It was also featured in Namco Museum Encore. The player takes control of "Albatross", a member of the WCPO''s (World Crime Police Organization) "Rolling Thunder" espionage unit. Albatross''s mission is to save a missing female agent named Leila Blitz from a secret society named Geldra located in New York City. Albatross must travel through two different segments or "stories", both comprised of five stages, for a total of ten game stages. On each stage, Albatross can enter doors, to hide and take cover from enemies, as well jump over to higher or lower floors with rails, including stairs. Albatross begins this game armed with a standard-issue pistol, which can be substituted with a fully automatic assault rifle that allows for continuous firing by holding down the firing button. Albatross can gain ammunition for either weapon, by entering doors which are marked "bullets" or "arms". Despite the presence of a life meter, Albatross can only take two physical hits from the enemy: a single hit drains half of the meter, and he will be killed instantly when struck by a projectile attack such as enemy bullets or lasers. (However, all bullets can be blocked by your own).' FROM games WHERE igdb_id = 12846 ON CONFLICT (game_id, language_code) DO NOTHING;
