INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Bond 007: Goldfinger', 'The player must stop Auric Goldfinger from taking the world''s gold supply, stop the destruction of Kentucky, deal with Pussy Galore and even a fight with Oddjob. Not much for old 007 to do actually - it''s all in a day''s work (or is it adventure)?' FROM games WHERE igdb_id = 1633 ON CONFLICT (game_id, language_code) DO NOTHING;
