INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Slog', 'A action-adventure game developed by David Walton and published by Alpha-Omega Software for ZX Spectrum. Captain Slog has to search for nine blueprints spread out around a spaceship maze full of wacko robots.' FROM games WHERE igdb_id = 60636 ON CONFLICT (game_id, language_code) DO NOTHING;
