INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('firework-thrower-kantaros-53-stations-of-the-tokaido--1', 48443, '1986-09-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nyt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2dei.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firework Thrower Kantaro''s 53 Stations of the Tokaido', 'Although commonly referred to as Toukaidou Gojuusan-tsugi, the full name of the game is Kanshakudama Nage Kantarou no Toukaidou Gojuusan-tsugi, which can be roughly translated as "explosive throwing Kantarou and the 53 stations of the Toukaidou". To further explain the main character''s name is Kantarou, and he throws bombs at his enemies. He is attempting to travel from Kyoto back to Edo (known today as Tokyo) to see his girlfriend Momoko. To get there, he is traveling through the Toukaidou highway which is composed of 53 checkpoints along the way. However, an unscrupulous merchant is attempting to capture Kantarou and steal his explosive technique secrets. Toukaidou Gojuusan-tsugi is a horizontally scrolling action game developed by Sunsoft in 1986. It was never released outside of Japan. On June 29, 2001, the game was released for the Windows platform as part of Sunsoft Classic Games 2 along with Ikki (which was itself rereleased as a budget title in 2004). On December 27, 2001, the game was released on the PlayStation as part of Memorial Series: Sunsoft Vol. 3 along with The Wing of Madoola.' FROM games WHERE igdb_id = 48443 ON CONFLICT (game_id, language_code) DO NOTHING;
