INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-quest-the-sarien-encounter', 28, '1986-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co321o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvca.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Quest: The Sarien Encounter', 'He''s out to clean up the universe... ...But he doesn''t do windows. Strap into your computer station and prepare for blast-off. If the thrilling graphics don''t blow you off your chair, the laughs will have you rolling on the floor. If you can help Roger Wilco he could use it. Hey, wake up! Roger Wilco''s the chief sanitation engineer (a.k.a. Janitor) on the starship Arcada. His mission: to scrub dirty decks... to replace burned-out lightbulbs... to boldly go where no man has swept the floor! But while he was napping in the broom closet, his starship was hijacked by the Sarien Stormtroopers. Now the top-secret Star Generator''s been stolen. And if Roger doesn''t get it back, the universe as we know it is toast! Kaboom! The Two Guys from Andromeda often travel the cosmos under the aliases of Scott Murphy and Mark Crowe. They''re best known for their award-winning Space Quest series and their frequent sightings with Elvis.' FROM games WHERE igdb_id = 28 ON CONFLICT (game_id, language_code) DO NOTHING;
