INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crackout', 48292, '1986-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8d5o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8d4r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crackout', 'Crackout is a video game that was released for the Nintendo Entertainment System by Konami in 1991. It is based upon Atari''s Breakout games of the 1970s. The object of the game is to clear levels by either destroying all bricks or defeating the enemies. There are four zones of eleven levels each. The zones are Cubic Zone, Mirror Zone, Tube Zone and Final Zone. This game differs from the original Breakout as it contained enemies on screen that could be hit to gain power ups. Powerups included a parachute to slow the ball down, multiple balls, or projectiles. There were also level warps in the form of "Konami Man", who would fly from top to bottom of the play area. There were typically 1 - 3 enemies on screen at once, appearing out of a trapdoor in the top corners, or let in through the side walls. Every few levels there was also a boss, ranging from a small dragon to a centipede. The bosses changed colour from Green to Blue to Pink, each time increasing in speed. Each level also contained a hidden letter which made up a password presented at the end of the game (Zone 4 Level 11). If this was not input correctly, the player restarted the game from the beginning. If the player input the password correctly, they were shown the end credits which consisted of a procession of the enemies from the game. The password is MERRYCHRISTMAS.' FROM games WHERE igdb_id = 48292 ON CONFLICT (game_id, language_code) DO NOTHING;
