INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chessmaster 2000', 'The Chessmaster 2000 is the most powerful computer chess program in the world today and the friendliest! It draws from a mammoth opening library of over 71,000 moves - the world''s largest. In mid-game, it displays amazing combinations of classical and modern strategy. At end game it calls further upon the world''s newest and finest computer chess algorithm to mount virtuoso tactics.' FROM games WHERE igdb_id = 13482 ON CONFLICT (game_id, language_code) DO NOTHING;
