INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-cycle', 28460, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9eyk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sz0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Cycle', 'A motorbike racing game strongly resembling Sega''s Hang-On titles. The game is viewed from behind the bike, which tilts as you turn. You are racing against the clock, although there are lots of other bikes on track to avoid and ride around. There are 3 skill levels, which affect the amount of time you have to complete the level, and the bonus offered if you manage to (the amount of time left, divided by a set number, bigger on lower levels). Your bike has 3 gears and appears to have a top speed of around 120 MPH. After every 2 races there''s a bonus round in which you must pick up as many tokens as possible in the time limit.' FROM games WHERE igdb_id = 28460 ON CONFLICT (game_id, language_code) DO NOTHING;
