INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'America''s Cup Challenge', 'The Official America''s Cup Sailing Simulation (aka Arnie''s America''s Cup Challenge, America''s Cup Challenge) was an above-average licensed title in its time. Play against the AI or one of your friends.  You can download it here:  https://www.myabandonware.com/game/the-official-america-s-cup-sailing-simulation-67a' FROM games WHERE igdb_id = 13312 ON CONFLICT (game_id, language_code) DO NOTHING;
