INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JaJaMaru no Daibouken', 'JaJaMaru no Daibouken is a Family Computer video game that was released exclusively for a Japanese market in 1986. The concept of the game is that the player controls a red ninja as he progress through a series of Japanesque levels defeating evil spirits that have spread across the land. The player can even ride his faithful frog if he can recover it from hiding.' FROM games WHERE igdb_id = 48457 ON CONFLICT (game_id, language_code) DO NOTHING;
