INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Number Munchers', 'Learn basic math skills with Number Munchers. Keep your Muncher away from the Troggles by munching on multiples, factors, prime numbers, equalities, and inequalities. If you can stay away from the Troggles and earn enough points, you''ll be part of the Muncher Hall of Fame.' FROM games WHERE igdb_id = 128661 ON CONFLICT (game_id, language_code) DO NOTHING;
