INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('athena-in-wonderland', 39710, '1986-07-01', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/o1z61rvug1bbqs3p1jxn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athena In Wonderland', 'In this game, players take the role of Athena, the Goddess of Wisdom, who has grown tired of her life within the castle and ventures into the Fantasy World beyond the castle walls. Strange and fearsome creatures will attack at every turn, but weapons can be found along the way: a ball and chain, a bow and arrow, and a mighty sword. Put on wings and take to the sky, or become a mermaid to explore the ocean depths.' FROM games WHERE igdb_id = 39710 ON CONFLICT (game_id, language_code) DO NOTHING;
