INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firestorm', 'Firestorm is a top-down shooter, but the game requires a bit of thinking. The titular hero is able to create destructive fire-balls, control computer memory banks and move inanimate objects with the power of telekinesis. He must rescue his girlfriend, who is imprisoned in criminal organization''s citadel. This citadel is a big maze, and the game has 12 levels.' FROM games WHERE igdb_id = 14070 ON CONFLICT (game_id, language_code) DO NOTHING;
