INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puszka Pandory', 'Puszka Pandory (English: Pandora''s Box) is a Polish computer text game created in 1986 by Marcin Borkowski for the ZX Spectrum 48k computer. The game achieved popularity after trading on the Grzybowska Commodity Exchange. According to the book Polish Bytes, the game is the first one written by a Pole, attempted to be sold in Poland, and whose description appeared in the Polish press.' FROM games WHERE igdb_id = 93586 ON CONFLICT (game_id, language_code) DO NOTHING;
