INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Le Pacte', 'e Pacte is an horror style adventure game published by the French Company Loriciels in 1986. The story revolves around the player being part of a team sent to investigate the house of Amityville, with two other parapsychologists called Evrett Wilson and Laura Relfod (plus their dog, Black). The game does not use a textual interface, like most of the adventure games of its time; instead the player has to associate two words within a very long list.' FROM games WHERE igdb_id = 304056 ON CONFLICT (game_id, language_code) DO NOTHING;
