INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sherlock-holmes-hakushaku-reijou-yuukai-jiken', 48396, '1986-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/e24xokztvfmkcgqqxdlm.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes: Hakushaku Reijou Yuukai Jiken', 'Sherlock Holmes: Hakushaku Reijou Yuukai Jiken (loosely translated as Sherlock Homes: Kidnapping of the Young Countess) is an adventure game developed for the Famicom by Towachiki, and released in 1986. The game puts the player in the role of Sherlock Holmes, who must travel throughout England (by train) while trying to solve the mystery of a kidnapping. In this unusual portrayal of Holmes, his only means of interrogating anyone to obtain information is by attacking them with jump kicks until they run out of stamina and reveal clues. The game alternates between a zoomed out view of England streets, where every bystander can damage Holmes simply by running in to him, to a zoomed in side scrolling view of buildings or sewers or parks. Besides interrogating people for information, or simply beating them up for train fare, Holmes must search seemingly random cracks or trees in order to find important clues, or inventory items.' FROM games WHERE igdb_id = 48396 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48396 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
