INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wanderer', 'Wanderer is a sci-fi adventure game combining card trading and space combat in a universe where cats have become a valuable currency. After the protagonist''s feline companion is held for ransom, players navigate through various planets, engaging in a poker-inspired card game with alien civilizations while collecting cats as rewards. Between trading sessions, players pilot their ship through vector-graphic 3D space battles and black hole sequences, shooting down enemy vessels in first-person combat to progress through the story.' FROM games WHERE igdb_id = 36866 ON CONFLICT (game_id, language_code) DO NOTHING;
