INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flower Power', 'An unusual multi-stage vertical shooter that is set in outer space. Eliminate attacking flowers and a variety of end-bosses. Shoot daisy-chains and comets for power-ups like speed, laser, missiles, and the cutter blade. Flower was produced by Komax in 1986. Komax released only 1 different machine in our database under this trade name.' FROM games WHERE igdb_id = 70191 ON CONFLICT (game_id, language_code) DO NOTHING;
