INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Juegue Con Su Amstrad 01: Kart 3000', 'This little game came in a standalone cassette as a free game with the first issue of the Spanish magazine "Juegue Con Su Amstrad", which roughly translates to "Play With Your Amstrad". The aim is simple: shoot everything in sight for points. Just don''t come in contact with anything, though. Just shoot, shoot, shoot!' FROM games WHERE igdb_id = 273528 ON CONFLICT (game_id, language_code) DO NOTHING;
