INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hacker II: The Doomsday Papers', 'Hacker II is notably more difficult and involved than the first game. In Hacker II, the player is actually recruited based upon his (assumed) success with the activities in the original game. Once again, they are tasked with controlling a robot, this time to infiltrate a secure facility in order to retrieve documents known only as "The Doomsday Papers" from a well guarded vault to ensure the security of the United States.' FROM games WHERE igdb_id = 12133 ON CONFLICT (game_id, language_code) DO NOTHING;
