INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trio', 'A collection of three educational mini-games from Macmillan aimed at pre-school kids. Sam Goes Shopping tasks the player with finding the right shop that sells a particular item and the department within it. Computer Snap is a colourful card matching game where youngsters have to match two pictures before the computer or their opponent. Tables Test is an opportunity for kids to test themselves on their knowledge of the times tables.' FROM games WHERE igdb_id = 287385 ON CONFLICT (game_id, language_code) DO NOTHING;
