INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Class Track Meet', 'Stadium Events/World Class Track Meet is a video game for the Nintendo Entertainment System that was first released in Japan in 1986 as Running Stadium. In America, the game was released in 1987 as Stadium Events, and then in 1988, it was rereleased as World Class Track Meet. The players compete against a runner in the Tournament Mode, and in 4 events for a total score in the Olympic Mode. The top 6 winners'' names and their scores will appear on the electronic billboard. It uses the Family Fun Fitness Control Mat.' FROM games WHERE igdb_id = 2242 ON CONFLICT (game_id, language_code) DO NOTHING;
