INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Up Periscope!', '"Up Periscope!" is a World War 2 submarine simulation set in the South Pacific. Destroy Japanese convoys to support your country''s war effort. Practice, campaign and historical modes are available.' FROM games WHERE igdb_id = 37160 ON CONFLICT (game_id, language_code) DO NOTHING;
