INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Star Force: Jikuureki no Himitsu', 'Super Star Force: Jikuureki no Himitsu is a video game developed and published by Tecmo on November 11, 1986 for the Family Computer only in Japan. The game was featured in episode 111 (14th Season) of GameCenter CX. While this video game was originally assigned by Hudson Soft to be the publisher, Tecmo (then known as Tehkan) decided to both develop and publish the game as they were the official copyright owners' FROM games WHERE igdb_id = 48394 ON CONFLICT (game_id, language_code) DO NOTHING;
