INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Runner', 'Sky Runner is a shoot''em up developed by Cascade Games. A Skimmer or a Skybike has to be flown over the surface of the fictional planet Naibmoloc and defence towers, armed enemy bikers and the Sky(a new drug)-producing harvesters have to be destroyed.' FROM games WHERE igdb_id = 36904 ON CONFLICT (game_id, language_code) DO NOTHING;
