INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trinity', 'Trinity is an interactive fiction computer game written by Brian Moriarty and published in 1986 by Infocom. The plot blends historical and fantastic elements as part of a prose poem regarding the destructive power of the atomic bomb and the futile nature of war in the atomic age. The name refers to the Trinity test, the first nuclear explosion, which took place in July 1945.' FROM games WHERE igdb_id = 2952 ON CONFLICT (game_id, language_code) DO NOTHING;
