INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter Events', 'Winter Events is a multi-sport event game heavily influenced by the classic Winter Games. The game allows you and three other friends to select a country before competing in six Olympic events which are Biathlon, Slalom Skiing, Ski Jumping, Speed Skating, Bobsleigh and Downhill Skiing (Downhill Skiing not on Atari 8-Bit).' FROM games WHERE igdb_id = 41012 ON CONFLICT (game_id, language_code) DO NOTHING;
