INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nuclear-bowls', 272502, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co791d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scp216.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nuclear Bowls', 'Bowls is the chief engineer of the most powerful nuclear power plant on earth. One morning, when he arrives at work, he finds that the nuclear reactor has melted down, and radiation has spread everywhere. The workers have been transformed into strange mutants, and the machines, possessed by wild energy, harass any intruder who dares to invade the reactor. In this video-adventure you will have to control Bowls and, immersed in your anti-radiation armor, you will have to use the objects distributed around the plant to rebuild the reactor, feed it with fuel, and start it up from the control room. To do this, you must first perform a series of tasks related to the achievement of your goal; all within a time limit, in anticipation of the final destruction of the plant because of its excessively prolonged exposure to radiation. In your Bowls backpack you can carry up to three objects, and a limited amount of heavy water, which will serve to provide you with energy for your defensive weapon. Now relax, forget your nerves and gather all the cold blood you can, because you are about to dive into the fascinating universe of NUCLEAR BOWLS. The adventure begins.' FROM games WHERE igdb_id = 272502 ON CONFLICT (game_id, language_code) DO NOTHING;
