INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Hunter', 'Space Hunter is a Japan-exclusive video game that was released in 1986 for the Family Computer. The game was published by Kemco; which was then known as Kotobuki System. The plot apparently revolves around a robotic revolt led by a robot named De Gaulle. It is the year 2199 AD. By the explosions of global nuclear war, society has broken up into nine small expulsions, one of them disappeared and Venus collided with another celestial object. Humanity only slightly survived. Its thread of life barely connected to a body; which was rebuilt into a cyborg. The heroine is named Al Tiana and is also apparently a robot who does not support the rebellion. She is out to prove her loyalty to the humans.' FROM games WHERE igdb_id = 271175 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 271175 AND c.slug = 'kotobuki-systems' ON CONFLICT DO NOTHING;
