INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vulcan: The Tunisian Campaign', 'Vulcan is a third entry in R. T. Smith''s World War II trilogy, including Arnhem and Desert Rats. It simulates the Tunisian Campaign in 1942-43 from the arrival of the ''Torch'' Task Force and their race for Tunis, to the final battle of ''Operation Vulcan''. There are 5 armies (3 Allied & 2 Axis) and 5 scenarios, including the battles of Kasserine and Mareth. Each scenario has several pre-conditions to start from, which include Axis control Malta, Axis capture Bone, DAK (Deutsches Afrika Korps) destroyed, Desert armies late, and French neutrality.' FROM games WHERE igdb_id = 72473 ON CONFLICT (game_id, language_code) DO NOTHING;
