INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stop Ball', 'The objective is to keep the spheres that appear on the screen in the air, although there will be phases in which our objective will be to avoid any contact with them. Fun arcade from Juliet software, a company very active in the early years of 8-bit computers (creator of other titles such as Antares), which would disappear when the Golden Age came.' FROM games WHERE igdb_id = 273013 ON CONFLICT (game_id, language_code) DO NOTHING;
