INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Promethean Prophecy', 'In "Star Trek: The Promethean Prophecy," the USS Enterprise is suddenly attacked, causing significant damage to multiple decks. Coolant leaks have contaminated the raw protein supply, essential for synthesized meals. Chief Engineer Scott predicts warp engine repairs will take at least eight to nine days. The crew faces potential starvation without a prompt food source.' FROM games WHERE igdb_id = 36593 ON CONFLICT (game_id, language_code) DO NOTHING;
