INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albatross: Tournament Golf', 'Albatross is a top view golf game that consists of an 18 holes course. You can select your own clubs from 14 drivers, irons and a putter. Further you can adjust your stance, how you hit the ball and your swing. It features a split screen with two views, an overhead view of the entire hole and a more detailed zoom of your ball''s current position. The screen also contains a status bar with all necessary information. The gameplay options include single player stroke play, multi player stroke play, or multi player match play.' FROM games WHERE igdb_id = 41665 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41665 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
