INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Kong 2: Yomigaeru Densetsu', 'A giant ape King Kong, which was shot and fell off the World Trade Center tower, appears to be alive, but is in coma for 10 years and desperately needs a blood transfusion in order to have an artificial heart implanted. Suddenly, in the rainforest, another gigantic ape is found - this time a female. She is brought to the USA, and the heart is successfully implanted. But then King Kong, having sensed the female ape, breaks loose.' FROM games WHERE igdb_id = 41689 ON CONFLICT (game_id, language_code) DO NOTHING;
