INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend', 'The player controls a young commander which uses a green armour and helmet and must defending the kingdom lands from invading enemies, following the orders and instructions given by the old king, for it you''ll have to use money to making defect the enemy and recruit under your commands to form a legion of soldiers and make uses of different arms collected on the way, like bombs and arrows to defeat other enemies while you jump and dodges his attacks, always avoiding contact with any enemy for not to die and continue his legendary journey.' FROM games WHERE igdb_id = 197955 ON CONFLICT (game_id, language_code) DO NOTHING;
