INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cobra''s Arc', 'Mix of conversational and point & click game where the messages sent to us by the game play a fundamental role but instead of conversing directly as in other text adventures, we must choose actions to perform from a menu of icons. The initial location of the player, the objects to find, the movements of the characters and the correct solution of some of the puzzles are randomized every time we start a game.' FROM games WHERE igdb_id = 39110 ON CONFLICT (game_id, language_code) DO NOTHING;
