INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koneko no Daibouken', 'Koneko no Daibouken: Chibi-chan ga Iku is an action game, originally developed and published by Casio for the MSX personal computers in 1986, only in Japan. It focuses on Chibi-chan traversing several cities to encounter his girlfriend, Pipi-chan. Koneko no Daibouken: Chibi-chan ga Iku received an unlicensed port for the Sega Master System in South Korea, being available only to certain multicarts. The bootleg game Super Penguin, which is a ROM hack of this game, was sold for the Master System as well, albeit in standalone format.' FROM games WHERE igdb_id = 328699 ON CONFLICT (game_id, language_code) DO NOTHING;
