INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coaster Race', 'It''s going to take all the driving skill. You can master to make it through the steeply banked turns and the great 360° loop, so open the throttle and let''er up -- you''er on your way to taking the checker flag.' FROM games WHERE igdb_id = 47519 ON CONFLICT (game_id, language_code) DO NOTHING;
