INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Terrors of Trantoss', 'Following a familiar theme, an evil power rises when an undead wizard once banished to the mountains of Mortran returns to terrorise the villagers of a small village in the fantasy land of Hapshal. The followers of the undead wizard Trantoss have been gathering the shattered pieces of the golden mace that once gave him his powers and the player takes control of two brothers, the strong woodcutter Lobo and the stealthy rogue Scarn whose mission is to thwart their evil plot.' FROM games WHERE igdb_id = 232557 ON CONFLICT (game_id, language_code) DO NOTHING;
