INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Goonies', 'The Goonies is a 1986 platform game. The main theme for most of the game is a chiptune rendition of Cyndi Lauper''s "The Goonies ''R'' Good Enough". The game was previously released only in Japan, but was later released as an Arcade Playchoice-10 title in North America.' FROM games WHERE igdb_id = 4615 ON CONFLICT (game_id, language_code) DO NOTHING;
