INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Maruo', 'Super Maruo is an unlicensed game released in Japan in 1986. Although very rare, this game is the first unlicensed Famicom game and the first unlicensed adult Famicom game as well. Despite the name, it has no relation to Mario at all.' FROM games WHERE igdb_id = 238973 ON CONFLICT (game_id, language_code) DO NOTHING;
