INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Las Vegas', 'Las Vegas is a Japan-exclusive graphical variant of Softporn Adventure, and hence can be seen as an earlier version of Leisure Suit Larry, which was released a few months later. The gameplay is, by and large, identical to the original text-only version, with the exception of a few adjustments made to the monetary system and a few commands handled slightly differently. Like before, the player types text commands consisting of combinations of verbs and objects. The game recognizes both Japanese and English inputs.' FROM games WHERE igdb_id = 91384 ON CONFLICT (game_id, language_code) DO NOTHING;
