INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8 Ball', '8 Ball is sport / snooker game from Atari ST released by MichTron, 1986. Developed and designed by Stanley Crane, Eight Ball lets you take the pool hall home on disk. This arcade-style game simulates the classic game of Eight Ball. Great graphics, sound and action make this exciting new game so real that each game will you in the limelight or behind the eight-ball.' FROM games WHERE igdb_id = 14150 ON CONFLICT (game_id, language_code) DO NOTHING;
