INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OrbQuest: The Search for Seven Wards', 'While casting a spell to banish the forces of evil, King Cricken vanished in a flash of thunder and the mystic relic known as the Orb was split into seven pieces and scattered through the land. Now, as evil seeps back into the world, you must travel in search of the pieces to reassemble the Orb and banish it once more.' FROM games WHERE igdb_id = 140450 ON CONFLICT (game_id, language_code) DO NOTHING;
