INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hypa Raid', 'Players take control of a CIA agent wearing a battery powered suit, as he tries to recover the pieces of the MIG Starfighter, a powerful aircraft, which are scattered around a military complex. Locked doors must be opened and security avoided. Any contact with enemies or booby traps will drain the suit''s batteries. If the suit''s batteries run out completely, the player will die.' FROM games WHERE igdb_id = 14123 ON CONFLICT (game_id, language_code) DO NOTHING;
