INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Falklands 82', 'Falklands ''82 (released as Malvinas ''82 in Spanish markets) is a 1986 turn-based strategy video game developed and published by Personal Software Services for the ZX Spectrum and Commodore 64. It is the fifth instalment of the Strategic Wargames series. The game is set during the 1982 Falklands War and revolves around the Argentine occupation and subsequent British re-capture of the Falkland Islands. The player controls the British Task Force as they must either defeat all Argentine forces on the archipelago or re-capture every settlement.' FROM games WHERE igdb_id = 14063 ON CONFLICT (game_id, language_code) DO NOTHING;
