INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hokuto-no-ken-violence-gekiga-adventure', 64195, '1986-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5rw8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/plk88xjtbseetgymrfzq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokuto no Ken: Violence Gekiga Adventure', 'Hokuto no Ken - Violence Gekiga Adventure​ is a graphic adventure game that was released for Japanese home computers by Enix on May 1986, making it the very first video game based on the Hokuto no Ken franchise. It was released for the NEC PC-8801, NEC PC-9801, FM7 and X1. The game''s story is loosely based on the Southern Cross story arc from the original manga. The objective is to help Kenshiro and Bat infiltrate the city of Southern Cross and defeat Shin. As with most adventure games, the player must navigate Ken and Bat through a menu-based command system that will allow them to obtain vital items that will lead them to their ultimate goal. Additionally, Kenshiro must also confront Shin''s various underlings throughout the course of the story. The fighting sequences uses a so-called "vital point system" (秘孔システム) in which an enemy can only be defeated by striking specific vital points. The player must search for information or clues that will help them figure out the weak spots of each enemy.' FROM games WHERE igdb_id = 64195 ON CONFLICT (game_id, language_code) DO NOTHING;
