INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thomas M. Disch''s Amnesia', 'Amnesia is an interactive text adventure. The game begins as the player''s character awakens in a midtown Manhattan hotel room with absolutely no memory. He has no clothes and no money, and doesn''t even remember what he looks like. The player soon discovers he is engaged to a woman he cannot remember, a strange man is trying to kill him, and the state of Texas wants him for murder. From here, the player must unravel the events in his life that led him to this point.' FROM games WHERE igdb_id = 50491 ON CONFLICT (game_id, language_code) DO NOTHING;
