INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChessBase 1.0', 'Starting in 1983, Frederic Friedel and his colleagues put out a magazine Computer-schach und Spiele covering the emerging hobby of computer chess. In 1985, Friedel invited then world chess champion Garry Kasparov to his house. Kasparov mused about how a chess database would make it easier for him to prepare for specific opponents. Friedel began working with Bonn physicist Matthias Wüllenweber who created the first such database, ChessBase 1.0, as software for the Atari ST. The February 1987 issue of Computer-schach und Spiele introduced the database program as well as the ChessBase magazine, a floppy disk containing chess games edited by chess grandmaster John Nunn.' FROM games WHERE igdb_id = 290378 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 290378 AND c.slug = 'wullenweber-matthias' ON CONFLICT DO NOTHING;
