INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ninja', 'Ninja Princess opens with a short cutscene of the princess Kurumi getting carried away in a palanquin - her castle Kanten has been seized by the traitor Zaemon Gyokuro, who obviously wants to get rid of her. But she escapes, transforms into a kunoichi and sets out to regain her home. Even though it''s basically all about running around killing people with knives, Ninja Princess clearly wants to be a girly game. Everything is bright and colorful with cartoon-like proportions, and when Kurumi gets hit by an enemy, she just sits on the floor and starts crying. It''s hard to resent the game its stereotyping, though, cause it''s just cute as a button - no surprise here, after all the graphics were designed by Flicky artist Yoshiki Kawasaki and Reiko Kodama of Phantasy Star fame.' FROM games WHERE igdb_id = 38634 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 38634 AND p.igdb_id = 52 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hercules', 36541, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkd5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5dix.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hercules', 'Hercules is a platform video game written by Steve Bak for the Commodore 64 and published by Interdisc in 1984. It was reissued in 1986 by Alpha Omega and ported to the Acorn Electron, BBC Micro, Commodore 16, Plus/4, and ZX Spectrum. Alpha Omega changed its name to The Power House shortly after publishing the game. It was later remade in 1990 as Yolanda for the Amiga and Atari ST, with updated graphics and a different main character Yolanda, the daughter of Hercules.' FROM games WHERE igdb_id = 36541 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 36541 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
