INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zunou-senkan-galg', 48488, '1986-01-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4erm.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zunou Senkan Galg', 'Zunou Senkan Galg ("Brain Battleship Galg"), referred to as just Galg by the game''s title screen, is a vertical-scrolling shoot-em-up in which the player must navigate a serious of canyon-like environments for missing pieces to a war machine. Each stage has at least one piece, so the player must visit them all in order to find the necessary number. In addition to this, there are numerous secrets hidden throughout the many stages of the game, and the player frequently has to choose between multiple paths which lead to different stages. The game advertises itself as a "RPG" on its box art, referring to this additional layer of complexity. Like The Tower of Druaga, it is considered a historically important game in Japan for the amount of secrets and mysteries it contains and the subsequent difficulty involved in reaching the end without this hidden knowledge. Therefore, it was one of the earliest games for the Famicom to feature its own printed game guide for players to follow. Zunou Senkan Galg is almost entirely unheard of outside of Japan, however, and has never seen a release outside of its native country. Though it was published by dB-Soft, the game was developed by a group named "Team Bioteckers". Galg is their only known video game credit.' FROM games WHERE igdb_id = 48488 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 48488 AND p.igdb_id = 99 ON CONFLICT DO NOTHING;
