INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Wrestling', 'Pro Wrestling is a pro wrestling video game developed and published by Nintendo. The game was the third wrestling game on the Nintendo Entertainment System (after M.U.S.C.L.E. and Tag Team Wrestling). It is one of Nintendo''s sports-themed games for the NES, alongside titles like Tennis, Golf, Soccer, Volleyball and Ice Hockey.' FROM games WHERE igdb_id = 9512 ON CONFLICT (game_id, language_code) DO NOTHING;
