INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantomas 2', 'Phantomas 2 is a video game developed by Dinamic Software in the golden age of Spanish software. It is set inside Count Dracula''s castle, where the player has to overcome a series of traps until the monster is killed. The video game is presented as an arcade video adventure combined with a platform video game. It was developed for the ZX Spectrum, Amstrad CPC, Commodore 64 platforms and, a year after its publication, also on MSX' FROM games WHERE igdb_id = 45344 ON CONFLICT (game_id, language_code) DO NOTHING;
