INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickybear Math 2', 'Stickybear Math 2 is an educational game released in 1986 for the Apple II, designed to reinforce basic math skills through interactive mini-games. Developed by Richard Hefter and Susan Dubicki and published by Optimum Resource in collaboration with Weekly Reader Family Software, it is part of the broader Stickybear series known for its engaging edutainment titles. The game features colorful animations, customizable difficulty levels, and a variety of math challenges aimed at children aged 5–9.' FROM games WHERE igdb_id = 311005 ON CONFLICT (game_id, language_code) DO NOTHING;
