INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('glider-rider', 13002, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mlvgortzbzqav4bz7xzd.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glider Rider', 'The player must destroy the reactors on the island by dropping grenades on them. The reactors are defended by laser gun towers which can be temporarily disabled by disrupting their control towers.  The player''s character rides a machine which is a combination motorcycle and hang glider. By driving down a mountainside and suddenly reversing direction, the player can take to the air. He can fly in any direction, or lose height, but cannot climb higher. There are many mountains on the island to help him achieve flight. To destroy a reactor he must fly over it dropping grenades.  On touching ground the motorcycle is restored. If the player falls in the sea he will be eaten by sharks.' FROM games WHERE igdb_id = 13002 ON CONFLICT (game_id, language_code) DO NOTHING;
