INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tarzan', 'Tarzan has returned to the jungle with his wife, Lady Jane Greystoke, but their holiday came to an end when Usanga, evil chief of the Wamabo, kidnaps Jane to force Tarzan into retrieving the seven gemstones that were stolen from his tribal shrine. These gemstones are believed to be the Eyes of the Rainbow, representing each color of the spectrum. Tarzan has been given three days to find the gemstones, otherwise Jane will be eaten by the tribal pet, Sheeta the Panther.' FROM games WHERE igdb_id = 28468 ON CONFLICT (game_id, language_code) DO NOTHING;
