INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elysion', 48509, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co96ze.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuwiz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elysion', 'Elysion is a traditional 8-bit JRPG that incorporates elements from various RPG games. While it starts with the player talking to the local King for exposition, similar to other traditional JRPGs, it takes inspiration from different games within the RPG genre. It shares similarities with the first Dragon Quest in appearance, offers the choice of multiple protagonists like in Final Fantasy, features real-time combat without screen transitions like Hydlide or Ys, and adopts the strategy of enemies only moving when the player does, as seen in strategic Roguelike dungeon crawlers like the Mystery Dungeon series. The main objective of the game is to defeat the evil demon Baal. However, before facing this final challenge, the player character is tested by the King. They are tasked with entering the dungeon beneath the castle and retrieving important quest items. Once they successfully complete this extensive dungeon, the protagonist is recognized as the Hero of God and can embark on a journey to defeat Baal. This entails exploring the continent to find magical scrolls and eventually acquiring special God-like equipment. The term "Elysion" refers to the Elysian Fields, an ancient Roman underworld reserved for honorable souls who died in battle.' FROM games WHERE igdb_id = 48509 ON CONFLICT (game_id, language_code) DO NOTHING;
