INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens: The Computer Game', 'Aliens: The Computer Game is a 1986 video game developed and published by Activision for the Commodore 64, Apple II based on the film of the same title. As Activision''s UK subsidiary Electric Dreams Software had independently released their own version of the game with the same title, the game was renamed for European release. Initially planned to be released as Aliens: The Second Part, it was finally published under the title Aliens: US Version with ports for the Amstrad CPC and ZX Spectrum produced by Mr Micro. Aliens is a series of six minigames strung together via graphical interactive sequences, akin to an adventure game, though the only interaction possible is advancing the dialog, displayed in speech balloons. The minigames are mostly action sequences that involve piloting a ship from Sulaco to the planet''s surface, recognizing equipment, and fighting aliens.' FROM games WHERE igdb_id = 36810 ON CONFLICT (game_id, language_code) DO NOTHING;
