INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After Shock', 'After Shock is an immersive graphic text adventure where you use your keyboard to interact with visuals and descriptive text. A catastrophic earthquake devastates the city, defying expert predictions of minimal damage. Now, the nuclear power plant on the outskirts faces a critical meltdown, and you, as the system''s designer, must navigate the treacherous post-earthquake landscape from your office to repair the cooling system.' FROM games WHERE igdb_id = 36565 ON CONFLICT (game_id, language_code) DO NOTHING;
