INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koneko Monogatari: The Adventures of Chatran', 'The story of two animals and their adventures. Chatran, the cat, and Pocky, the dog, are two animals who grew up together on the same farm. One day, the two are separated and begin a journey to find each other. The adventurous, and often perilous quest finds the two animals traveling across mountains, plains, and snow-covered lands searching for one another.' FROM games WHERE igdb_id = 41271 ON CONFLICT (game_id, language_code) DO NOTHING;
