INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('breakers', 28707, '1986-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/d3zn5rvebib2t4sko0ot.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakers', 'Somewhere in Hong Kong, two martial artists face each other in a vast courtyard. The challenger is a stout man in brown skin. The ground has been tainted with blood. However, his crescent blade hasn''t touched his opponent yet. It was a one-sided battle. He was already exhausted and it won''t be long before he would fall. "Fool, you will become one of my family" resounded the opponent''s voice, as the challenger crumbled to the floor and was turned into sand. The Fighting Instinct Tournament, or FIST, is a tournament as fierce as its name suggests. There was no shortage of martial artists who entered the tournament seeking fame, and yet there were many who left the tournament as corpses. The last challenger who remains in this lawless tournament gets to challenge the organizer of the tournament, the Head of the Huang Financial Clique, for the chance to win the massive prize money. The martial artist who can manage to defeat him will obtain the honor of truly calling him or herself the strongest. However, none of the martial artists who were chosen to challenge the champion in a private final match have ever come back alive. Nobody knows when exactly the tournament is held, since only an avaricious will was spiraling over there. The sponsor is actually an evil spirit who possessed the body of a modern man from Hong Kong who has established a selection system to amplify his dark powers. The FIST tournament has gathered numerous participants from around the globe and another sacrifice will be chosen this year.' FROM games WHERE igdb_id = 28707 ON CONFLICT (game_id, language_code) DO NOTHING;
