INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MagMax', 'A horizontal scrolling shooter, players control the title hover ship in an attempt to completely construct the ship into a giant robot and to destroy any enemies attempting to stop it. The three-headed mechanical dragon found as a boss character in the game, known as Babylon, strongly resembles Mecha-King Ghidorah from the Godzilla franchise.' FROM games WHERE igdb_id = 29033 ON CONFLICT (game_id, language_code) DO NOTHING;
