INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robox', 'A German text adventure game with High-Res graphics and text published in 64''er Software Extra Nr.04: Abenteuer-Spiele - Volume 1. In the distant future you''re the winner of a trip to a holiday planet. And an adventure ensues....Swiss Commodore 64 game developed by Laro Schatzer and Marc Pilloud.' FROM games WHERE igdb_id = 319997 ON CONFLICT (game_id, language_code) DO NOTHING;
