INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu Kouha Kunio-kun', 'Hiroshi is a student at Nekketsu High School, and is always bullied by everyone. One day, one man arrives at the school who changes everything. His name is Kunio!! Fighting the bullies! He looks tough, but he is a kind-hearted man. Kunio and Hiroshi become close friends. However, one day Hiroshi is kidnapped by someone. Kunio stands up and faces the gangs at Nekketsu High School to rescue his friend.' FROM games WHERE igdb_id = 40969 ON CONFLICT (game_id, language_code) DO NOTHING;
