INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokuto no Ken', 'Hokuto no Ken for the Family Computer (Famicom for short) is a side-scrolling action video game published by Toei Animation and developed by Shouei Systems. It was released on August 10, 1986 exclusively in Japan and was the first of four Hokuto no Ken video games released for the Famicom. While it features gameplay similar to Sega''s earlier Mark III version of Hokuto no Ken, it is an unrelated game made by a different developer.' FROM games WHERE igdb_id = 46115 ON CONFLICT (game_id, language_code) DO NOTHING;
