INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('musashi-no-ken-tadaima-shugyou-chuu', 48417, '1986-09-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/b5hiriskxbs9vnghivbb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musashi no Ken: Tadaima Shugyou-chuu', 'Musashi no Ken: Tadaima Shugyou-chuu is a 1986 video game software developed and published by Taito exclusively in Japan. It is based on a Japanese sports manga series written and illustrated by Motoka Murakami that focuses on kendo, simply titled Musashi no Ken. The gameplay and design in the one-on-one fighting parts resemble Taito''s other fighting game, Great Swordsman, especially its kendo mode. The game''s plot is about the son of two Kendo champions named Musashi. He strives to become as great at Kendo as his parents. The entire story centers around the world of Kendo and its up and coming competitors. The anime is broken up in to two parts. The first part follows Musashi''s early years in grade school while the second part follows his high school years. In the first episode, Musashi befriends an Akita puppy who is by his side throughout the series.' FROM games WHERE igdb_id = 48417 ON CONFLICT (game_id, language_code) DO NOTHING;
