INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Footballer of the Year', 'You''re a 17-year-old apprentice in the 4th Division with only £5,000 and 10 goals to your name. Have you got what it takes to cope with the trauma of transfer deals, injuries and other match day problems, while displaying skill and professionalism in matches throughout Europe. Rise through the divisions, out-classing rivals on the way to prove you are the best and gain the highest accolade... FOOTBALLER OF THE YEAR!' FROM games WHERE igdb_id = 41005 ON CONFLICT (game_id, language_code) DO NOTHING;
