INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Relics', 'Relics is an action-adventure game where players take the role of a spirit who can possess different characters. The spirit appears at underwater ruins with no explanation why it became a spirit and what it needs to do. In fact, one will only find out about the story of the game when seeing the real ending. The graphic style of the game is compared to the works of H. R. Giger.' FROM games WHERE igdb_id = 202896 ON CONFLICT (game_id, language_code) DO NOTHING;
