INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun', 'Top Gun is a 1986 combat flight simulation game based on the film of the same name. It was developed and published by British company Ocean Software, and was released for several computer platforms. In the United Kingdom, it was released for Amstrad CPC, Commodore 64, and ZX Spectrum in December 1986. The following year, it was released for Atari ST. In the United States, it was published by Thunder Mountain. In 1989, it was published by The Hit Squad as a budget re-release for ZX Spectrum and Commodore 64.' FROM games WHERE igdb_id = 22910 ON CONFLICT (game_id, language_code) DO NOTHING;
