INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Continuum', 'When the very first Macintosh computer came out (128K RAM, 400k floppy) in 1984, my brother Randy Wilson wrote a video game called originally "Gravity Well" internally, and eventually "Continuum" when it was released (when released it was unable to run on the 128K Mac, instead it required the very next upgraded model of 512K).' FROM games WHERE igdb_id = 229019 ON CONFLICT (game_id, language_code) DO NOTHING;
