INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starglider', 'Starglider is a 3D video game released in 1986 by Rainbird. It was developed by Argonaut Software, led by programmer Jez San. The game was inspired by Jez San''s love of the 1983 Atari coin-op Star Wars.  It was followed in 1988 by a sequel, Starglider 2.' FROM games WHERE igdb_id = 12778 ON CONFLICT (game_id, language_code) DO NOTHING;
