INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Math Rabbit', 'Math Rabbit is a 1986 video game that serves as a spin-off to the Reader Rabbit edutainment series. It was made by The Learning Company for DOS and Apple II. A Deluxe version was released in 1993 for DOS, Macintosh, and Windows 3.x. Then in 1997, the game was remade for Windows and Macintosh under the title "Reader Rabbit''s Math 1". The final remake for Windows and Macintosh in 1998 was titled "Reader Rabbit''s Math Ages 4-6", with a personalized version released in 1999.' FROM games WHERE igdb_id = 228786 ON CONFLICT (game_id, language_code) DO NOTHING;
