INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starflight', 'Starflight is a space exploration role-playing adventure video game developed by Binary Systems and published by Electronic Arts in 1986. Originally developed for IBM compatible and Tandy systems, it was later released for the Amiga, Atari ST, Macintosh and Commodore 64. A fully revamped version of the game was developed for the Sega Mega Drive/Genesis in 1991. Set in the year 4620, the game puts players in the role of a starship captain sent to explore the galaxy. There is no set path, allowing players to switch freely between mining, ship-to-ship combat, and alien diplomacy. The broader plot of the game emerges slowly, as the player discovers that an ancient race of beings is causing stars to flare and destroy all living creatures.' FROM games WHERE igdb_id = 2886 ON CONFLICT (game_id, language_code) DO NOTHING;
